                        });
                    } catch (e) {}
                    try {
                        jira_move_to_status({ key: ticketKey, statusName: statuses.IN_REVIEW });
                        console.log('✅ Moved', ticketKey, 'to In Review');
                    } catch (e) { console.warn('Failed to move to In Review:', e); }
                    removeLabels(ticketKey, params);
