    }
}

function hasCodeGraphUsage() {
    try {
        const raw = file_read({ path: '.dmtools/codegraph-usage.log' });
        return !!(raw && raw.trim());
    } catch (e) {
        return false;
    }
}

function removeLabels(ticketKey, params) {
    const wipLabel = params.metadata && params.metadata.contextId
