        if (command === 'git ls-remote --heads origin ' + branchName) return 'abc123\trefs/heads/' + branchName;
        if (command.indexOf('gh pr create') === 0) {
            if (opts.prCreateFails) throw new Error('HTTP 502: GraphQL: Bad Gateway');
