            forceOutput.indexOf('error: failed to push') !== -1 ||
            forceOutput.indexOf('push declined') !== -1;
        if (forceFailed) {
            return { success: false, isPushFailure: true, error: 'Push still rejected after force: ' + forceOutput.substring(0, 300) };
