        return raw;
    }
    // Some DMTools versions wrap the diff in a JSON envelope like {"result": "diff ..."}
    // or serialize an IBody lambda as {"arg$1": "diff ..."}. Unwrap those first.
    var trimmed = raw.trim();
    if (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {
        try {
