    try {
        pushOutput = runCmd({ command: 'git push -u origin ' + branchName }) || '';
    } catch (pushErr) {
        pushOutput = String(pushErr);
        pushThrewException = true;
    }

    var pushFailed = pushThrewException ||
        pushOutput.indexOf('remote rejected') !== -1 ||
