        });

        runCmd({
            command: 'git config user.email "' + config.git.authorEmail + '"'
        });

        console.log('✅ Configured git author as AI Teammate');
        return true;

    } catch (error) {
        console.error('Failed to configure git author:', error);
        return false;
    }
}

